<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { api } from './session'
import { formatDate } from './domain'
interface Policy { enabled: boolean; candidate_days: number | null; audit_days: number | null; purpose: string; legal_basis: string; revision: number }
interface Preview { id: string; policy_revision: number; as_of: string; expires_at: string; candidates: { id: string; full_name: string; last_activity_at: string }[]; audit_events: number; candidate_limit: number; audit_limit: number }
const route = useRoute(), policy = ref<Policy | null>(null), preview = ref<Preview | null>(null), holds = ref<{ id: string; full_name: string; reason: string }[]>([])
const form = reactive({ enabled: false, candidate_days: '', audit_days: '', purpose: '', legal_basis: '' })
const holdID = ref(String(route.query.candidate_id || '')), holdName = ref(''), holdReason = ref(''), phrase = ref(''), busy = ref(false), error = ref(''), notice = ref('')
const days = (value: string) => value === '' ? null : Number(value)
const dirty = computed(() => !policy.value || form.enabled !== policy.value.enabled || days(form.candidate_days) !== policy.value.candidate_days || days(form.audit_days) !== policy.value.audit_days || form.purpose !== policy.value.purpose || form.legal_basis !== policy.value.legal_basis)
function setPolicy(value: Policy) { policy.value = value; Object.assign(form, { enabled: value.enabled, candidate_days: value.candidate_days?.toString() || '', audit_days: value.audit_days?.toString() || '', purpose: value.purpose, legal_basis: value.legal_basis }) }
async function loadHolds() { holds.value = (await api<{ items: typeof holds.value }>('/retention/holds')).items }
onMounted(async () => { busy.value = true; try { setPolicy(await api<Policy>('/retention')); await loadHolds(); if (holdID.value) holdName.value = (await api<{ full_name: string }>('/candidates/' + encodeURIComponent(holdID.value))).full_name } catch (err) { error.value = (err as Error).message } finally { busy.value = false } })
async function save() { busy.value = true; error.value = ''; notice.value = ''; try { setPolicy(await api<Policy>('/retention', { method: 'PATCH', body: JSON.stringify({ enabled: form.enabled, candidate_days: days(form.candidate_days), audit_days: days(form.audit_days), purpose: form.purpose, legal_basis: form.legal_basis, base_revision: policy.value?.revision || 0 }) })); preview.value = null; phrase.value = ''; notice.value = 'Правила хранения сохранены' } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
async function prepare() { if (dirty.value) return; busy.value = true; error.value = ''; notice.value = ''; try { preview.value = await api<Preview>('/retention/preview', { method: 'POST', body: '{}' }); phrase.value = '' } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
async function apply() { if (!preview.value || dirty.value) return; busy.value = true; error.value = ''; notice.value = ''; try { const result = await api<{ candidates_erased: number; candidates_skipped: number; audit_events_deleted: number }>('/retention/previews/' + preview.value.id + '/apply', { method: 'POST', body: JSON.stringify({ confirmation: phrase.value }) }); notice.value = 'Очистка завершена. Карточек очищено: ' + result.candidates_erased + ', пропущено: ' + result.candidates_skipped + ', событий удалено: ' + result.audit_events_deleted; preview.value = null; phrase.value = ''; await loadHolds() } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
async function hold(id: string, enabled: boolean) { busy.value = true; error.value = ''; notice.value = ''; try { await api('/candidates/' + encodeURIComponent(id) + '/retention-hold', { method: 'PUT', body: JSON.stringify({ hold: enabled, reason: enabled ? holdReason.value : '' }) }); await loadHolds(); notice.value = enabled ? 'Запрет очистки установлен' : 'Запрет очистки снят'; holdID.value = ''; holdName.value = ''; holdReason.value = '' } catch (err) { error.value = (err as Error).message } finally { busy.value = false } }
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">УПРАВЛЕНИЕ ДАННЫМИ</p><h1>Хранение данных</h1><p class="subtitle">Правила организации и очистка после предпросмотра.</p></div></div>
  <p v-if="error" class="form-error" role="alert">{{ error }}</p><p v-if="notice" class="form-success" role="status">{{ notice }}</p>
  <form class="editor-card governance-policy" @submit.prevent="save"><h2>Правила хранения</h2><p class="muted-text">Сроки должны соответствовать утверждённой политике организации. Автоматической очистки по расписанию нет. Пустой срок означает, что этот тип данных не включён в очистку.</p><div class="form-grid"><label class="form-field">Контактные данные кандидата, дней<input v-model="form.candidate_days" type="number" min="1" max="36500" step="1" aria-label="Срок хранения кандидатов" :disabled="busy" /></label><label class="form-field">Журнал аудита, дней<input v-model="form.audit_days" type="number" min="1" max="36500" step="1" aria-label="Срок хранения аудита" :disabled="busy" /></label></div><label class="form-field">Цель хранения<textarea v-model="form.purpose" maxlength="2000" :required="form.enabled" :disabled="busy" /></label><label class="form-field">Утверждённое основание<textarea v-model="form.legal_basis" maxlength="2000" :required="form.enabled" :disabled="busy" /></label><label class="check-field"><input v-model="form.enabled" type="checkbox" :disabled="busy" />Включить применение правил хранения</label><button class="primary-button" :disabled="busy || !dirty">Сохранить правила</button><p v-if="policy" class="muted-text">Версия правил: {{ policy.revision }}. {{ policy.enabled ? 'Правила включены' : 'Очистка выключена' }}.</p></form>
  <section class="editor-card governance-policy"><h2>Предпросмотр очистки</h2><p>Удаляются ФИО, почта, телефон, записи согласий и адреса сообщений выбранных кандидатов; их ссылки отзываются. Баллы и ответы остаются без контактной карточки. Старые события аудита удаляются отдельно по заданному сроку.</p><p class="muted-text">Срок кандидата считается от последнего изменения карточки, приглашения, попытки или согласия. Активные прохождения, действующие ссылки и запреты очистки исключаются. За один запуск — до 100 кандидатов и 1000 событий. Файлы экспорта и резервные копии обрабатываются отдельно по политике организации.</p><button class="secondary-button" :disabled="busy || dirty || !policy?.enabled" @click="prepare">Подготовить предпросмотр</button><p v-if="dirty" class="muted-text">Сначала сохраните изменения правил.</p>
    <template v-if="preview"><h3>Что будет очищено</h3><p>Кандидатов: {{ preview.candidates.length }}. Старых событий аудита: {{ preview.audit_events }}.</p><p class="muted-text">Версия {{ preview.policy_revision }} · действует до {{ formatDate(preview.expires_at) }}.</p><ul class="retention-candidates"><li v-for="candidate in preview.candidates" :key="candidate.id"><RouterLink :to="'/candidates/' + candidate.id">{{ candidate.full_name }}</RouterLink><span>Последняя активность: {{ formatDate(candidate.last_activity_at) }}</span></li></ul><p v-if="!preview.candidates.length">Контактных карточек для очистки нет.</p><label class="form-field">Для подтверждения введите УДАЛИТЬ ПО ПРАВИЛАМ<input v-model="phrase" aria-label="Подтверждение очистки" autocomplete="off" :disabled="busy || dirty" /></label><button class="danger-button" :disabled="busy || dirty || phrase !== 'УДАЛИТЬ ПО ПРАВИЛАМ' || !preview.candidates.length && !preview.audit_events" @click="apply">Применить очистку</button><p class="muted-text">Перед выполнением сервер повторно проверит условия. Неподходящие записи будут пропущены. Операция необратима в приложении.</p></template>
  </section>
  <section class="editor-card governance-policy"><h2>Запреты очистки</h2><p class="muted-text">Для обязательного хранения или открытого спора установите запрет с причиной. В журнал попадёт факт изменения, без текста причины. Здесь показаны первые 100 запретов.</p><form @submit.prevent="hold(holdID, true)"><p v-if="holdName">{{ holdName }}</p><label class="form-field">ID кандидата<input v-model="holdID" required aria-label="ID кандидата для запрета" :disabled="busy" /></label><label class="form-field">Причина запрета<textarea v-model="holdReason" required maxlength="2000" :disabled="busy" /></label><button class="secondary-button" :disabled="busy || !holdID || !holdReason.trim()">Установить запрет</button></form><ul class="retention-candidates"><li v-for="candidate in holds" :key="candidate.id"><RouterLink :to="'/candidates/' + candidate.id">{{ candidate.full_name }}</RouterLink><p>{{ candidate.reason }}</p><button class="secondary-button" :disabled="busy" @click="hold(candidate.id, false)">Снять запрет</button></li></ul>
  </section>
</template>
